#include "push_swap.h"

int max_bits(t_node **a)
{
    t_node *tmp;
    int     i;
    int bits;
    int num;

    bits = 0;
    tmp = *a;
    while (tmp != NULL)
    {
        i = 0;
        num = tmp->rank;
        while (num > 0)
        {
            i++;
            num >>= 1;
        }
        if ( i > bits)
            bits = i;
        tmp = tmp->next;
    }
    return (bits);
}

void radix_sort(t_node **a, t_node **b)
{
    int bits;
    int i;
    int size;

    rank_list(a);
    i = 0;
    bits = max_bits(a);
    while( i < bits)
    {
        size = stack_length(*a);
        while(size > 0)
        {
            if (((*a)->rank & (1 << i)) == 0)
                pb(a,b);
            else
                ra(a);
            size--;
        }
        while(*b != NULL)
            pa(a,b);
        i++;
    }
}
